<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{Activity,Blocks,CheckCircle2,FileClock,KeyRound,RefreshCw,Save,Settings,ShieldCheck,ToggleLeft,Users}from'lucide-vue-next';import{useAuthStore}from'@/stores/useAuthStore';import{auditTone,userStatusLabel}from'@/features/system/systemModel';type User={id:string;username:string;displayName:string;department:string;roles:string[];status:string;lastLogin:string};type Role={id:string;name:string;description:string;users:number;permissions:string[]};type Module={code:string;name:string;enabled:boolean;order:number;permission:string};type Audit={id:string;time:string;actor:string;action:string;resource:string;ip:string;result:string;detail:string};type Setting={key:string;name:string;value:string;category:string;description:string};type Summary={users:number;activeUsers:number;roles:number;modules:number;auditsToday:number};const auth=useAuthStore(),summary=ref<Summary>(),users=ref<User[]>([]),roles=ref<Role[]>([]),modules=ref<Module[]>([]),audits=ref<Audit[]>([]),settings=ref<Setting[]>([]),tab=ref<'users'|'roles'|'modules'|'audits'|'settings'>('users'),selectedRole=ref<Role>();const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function load(){[summary.value,users.value,roles.value,modules.value,audits.value,settings.value]=await Promise.all(['summary','users','roles','modules','audits','settings'].map(x=>fetch('/api/v1/system/'+x,{headers:headers.value}).then(r=>r.json())))}async function toggle(u:User){await fetch(`/api/v1/system/users/${u.id}/toggle`,{method:'POST',headers:headers.value});await load()}async function saveRole(){if(!selectedRole.value)return;await fetch(`/api/v1/system/roles/${selectedRole.value.id}/permissions`,{method:'PUT',headers:headers.value,body:JSON.stringify({permissions:selectedRole.value.permissions})});await load()}onMounted(load)</script>
<template><section class="system-page"><header class="system-heading"><div><span>PLATFORM GOVERNANCE</span><h1>系统管理中心</h1><p>身份、权限、模块、审计与平台参数统一治理</p></div><button @click="load"><RefreshCw/>刷新配置</button></header><div class="system-summary"><article><Users/><span>平台用户<strong>{{summary?.users}}</strong><small>{{summary?.activeUsers}} 个正常</small></span></article><article><ShieldCheck/><span>角色数量<strong>{{summary?.roles}}</strong></span></article><article><Blocks/><span>启用模块<strong>{{summary?.modules}}</strong></span></article><article><FileClock/><span>今日审计<strong>{{summary?.auditsToday}}</strong></span></article></div><div class="system-workspace"><aside><button v-for="x in [{id:'users',n:'用户与组织',i:Users},{id:'roles',n:'角色权限',i:KeyRound},{id:'modules',n:'模块配置',i:Blocks},{id:'audits',n:'审计日志',i:FileClock},{id:'settings',n:'平台参数',i:Settings}]" :key="x.id" :class="{active:tab===x.id}" @click="tab=x.id as typeof tab"><component :is="x.i"/>{{x.n}}</button></aside><main><template v-if="tab==='users'"><header><div><h2>用户与组织</h2><span>管理平台账号、部门与角色绑定</span></div></header><div class="system-table user-table"><div class="table-head"><span>用户</span><span>部门</span><span>角色</span><span>最后登录</span><span>状态</span><span>操作</span></div><div v-for="u in users" :key="u.id"><span><strong>{{u.displayName}}</strong><small>{{u.username}}</small></span><span>{{u.department}}</span><span><b v-for="r in u.roles" :key="r">{{r}}</b></span><span>{{u.lastLogin}}</span><span><em :data-status="u.status">{{userStatusLabel(u.status)}}</em></span><span><button @click="toggle(u)"><ToggleLeft/>切换</button></span></div></div></template><template v-else-if="tab==='roles'"><header><div><h2>角色权限</h2><span>按职责配置最小权限集合</span></div></header><div class="role-grid"><button v-for="r in roles" :key="r.id" :class="{active:selectedRole?.id===r.id}" @click="selectedRole={...r,permissions:[...r.permissions]}"><ShieldCheck/><div><strong>{{r.name}}</strong><span>{{r.description}}</span><small>{{r.users}} 个用户 · {{r.permissions.length}} 项权限</small></div></button></div><section v-if="selectedRole" class="permission-editor"><header><h3>{{selectedRole.name}} 权限</h3><button class="primary" @click="saveRole"><Save/>保存权限</button></header><label v-for="p in ['dashboard:view','cmdb:view','cmdb:manage','topology:view','monitor:view','monitor:manage','job:manage','ticket:manage','release:view','toolbox:use','aiops:view']" :key="p"><input v-model="selectedRole.permissions" type="checkbox" :value="p">{{p}}</label></section></template><template v-else-if="tab==='modules'"><header><div><h2>模块配置</h2><span>控制平台模块启用状态与菜单顺序</span></div></header><div class="module-grid"><article v-for="m in modules" :key="m.code"><Blocks/><div><strong>{{m.name}}</strong><span>{{m.code}} · {{m.permission}}</span></div><b>顺序 {{m.order}}</b><em>{{m.enabled?'已启用':'已停用'}}</em></article></div></template><template v-else-if="tab==='audits'"><header><div><h2>审计日志</h2><span>记录关键管理与运维操作</span></div></header><div class="audit-list"><article v-for="a in audits" :key="a.id"><time>{{a.time}}</time><i :data-tone="auditTone(a.result)"></i><div><strong>{{a.actor}} · {{a.action}}</strong><span>{{a.resource}} · {{a.detail}}</span></div><code>{{a.ip}}</code><b>{{a.result}}</b></article></div></template><template v-else><header><div><h2>平台参数</h2><span>系统运行、安全与数据保留策略</span></div></header><div class="setting-list"><label v-for="s in settings" :key="s.key"><div><b>{{s.category}}</b><strong>{{s.name}}</strong><span>{{s.description}}</span></div><input v-model="s.value"><code>{{s.key}}</code></label></div></template></main></div></section></template>
